input.command:
sed -i 's|_expand(included, os.path.dirname(real), stack + (real,))|_expand(included, os.path.dirname(target), stack + (real,))|; s|_expand(lines, os.path.dirname(real), (real,))|_expand(lines, os.path.dirname(path), (real,))|' miniconf/loader.py && mkdir -p scratch/sub && printf 'a=1
@include b.conf
c=3
' > scratch/a.conf && printf 'a=2
c=2
@include sub/c.conf
' > scratch/b.conf && printf 'd=4
@include ../b.conf
' > scratch/sub/c.conf && printf 'x=1
@include nope.conf
' > scratch/m.conf && printf 'k=1
@include ok.conf
@include ok.conf
' > scratch/dia.conf && printf 'z=9
' > scratch/ok.conf && python -c "
from miniconf.loader import load
for f in ['scratch/a.conf','scratch/m.conf','scratch/dia.conf']:
    try: print(load(f))
    except Exception as e: print(type(e),e)
c=load('examples/service.conf');print(c.get('level',section='logging'),c.get('port',section='http'))
" && python -m unittest discover 2>&1 | tail -3; rm -rf scratch

